enum Error {
  GOPOST_OK(0),
  GOPOST_ERROR_INVALID_ARGUMENT(-1),
  GOPOST_ERROR_OUT_OF_MEMORY(-2),
  GOPOST_ERROR_NOT_INITIALIZED(-3),
  GOPOST_ERROR_ALREADY_INITIALIZED(-4),
  GOPOST_ERROR_GPU_NOT_AVAILABLE(-5),
  GOPOST_ERROR_CODEC_NOT_FOUND(-6),
  GOPOST_ERROR_IO(-7),
  GOPOST_ERROR_CRYPTO(-8),
  GOPOST_ERROR_UNKNOWN(-99);

  final int value;
  const Error(this.value);

  static Error fromValue(int value) => switch (value) {
    0 => GOPOST_OK,
    -1 => GOPOST_ERROR_INVALID_ARGUMENT,
    -2 => GOPOST_ERROR_OUT_OF_MEMORY,
    -3 => GOPOST_ERROR_NOT_INITIALIZED,
    -4 => GOPOST_ERROR_ALREADY_INITIALIZED,
    -5 => GOPOST_ERROR_GPU_NOT_AVAILABLE,
    -6 => GOPOST_ERROR_CODEC_NOT_FOUND,
    -7 => GOPOST_ERROR_IO,
    -8 => GOPOST_ERROR_CRYPTO,
    -99 => GOPOST_ERROR_UNKNOWN,
    _ => throw ArgumentError('Unknown value for Error: $value'),
  };
}

