    3 => GOPOST_ORIENTATION_ROTATE_180,
    4 => GOPOST_ORIENTATION_FLIP_V,
    5 => GOPOST_ORIENTATION_TRANSPOSE,
    6 => GOPOST_ORIENTATION_ROTATE_90,
    7 => GOPOST_ORIENTATION_TRANSVERSE,
    8 => GOPOST_ORIENTATION_ROTATE_270,
    _ => throw ArgumentError('Unknown value for ExifOrientation: $value'),
  };
}

final class ImageInfo extends ffi.Struct {
  @ffi.Int32()
  external int width;

  @ffi.Int32()
  external int height;

  @ffi.Int32()
  external int channels;

  @ffi.UnsignedInt()
  external int formatAsInt;

  ImageFormat get format => ImageFormat.fromValue(formatAsInt);

  @ffi.UnsignedInt()
  external int orientationAsInt;

  ExifOrientation get orientation =>
      ExifOrientation.fromValue(orientationAsInt);

  @ffi.Int32()
  external int has_alpha;

  /// 0=sRGB, 1=DisplayP3, 2=AdobeRGB
  @ffi.Int32()
  external int color_space;
}

/// --- Encoder (S5-02) ---
final class JpegEncodeOpts extends ffi.Struct {
  /// 1-100, default 85
  @ffi.Int32()
  external int quality;

  /// 0 or 1
  @ffi.Int32()
  external int progressive;
}

final class PngEncodeOpts extends ffi.Struct {
  /// 0-9, default 6
  @ffi.Int32()
  external int compression_level;
}

final class WebpEncodeOpts extends ffi.Struct {
  /// 1-100, default 80
  @ffi.Int32()
  external int quality;

  /// 0 or 1
  @ffi.Int32()
  external int lossless;
}

final class Canvas extends ffi.Opaque {}

/// --- Enums ---
enum LayerType {
  GOPOST_LAYER_IMAGE(0),
  GOPOST_LAYER_SOLID_COLOR(1),
  GOPOST_LAYER_TEXT(2),
  GOPOST_LAYER_SHAPE(3),
  GOPOST_LAYER_GROUP(4),
  GOPOST_LAYER_ADJUSTMENT(5),
  GOPOST_LAYER_GRADIENT(6),
  GOPOST_LAYER_STICKER(7);

  final int value;
  const LayerType(this.value);

  static LayerType fromValue(int value) => switch (value) {
    0 => GOPOST_LAYER_IMAGE,
    1 => GOPOST_LAYER_SOLID_COLOR,
    2 => GOPOST_LAYER_TEXT,
    3 => GOPOST_LAYER_SHAPE,
    4 => GOPOST_LAYER_GROUP,
    5 => GOPOST_LAYER_ADJUSTMENT,
    6 => GOPOST_LAYER_GRADIENT,
    7 => GOPOST_LAYER_STICKER,
    _ => throw ArgumentError('Unknown value for LayerType: $value'),
  };
}

enum BlendMode {
  GOPOST_BLEND_NORMAL(0),
  GOPOST_BLEND_MULTIPLY(1),
  GOPOST_BLEND_SCREEN(2),
  GOPOST_BLEND_OVERLAY(3);

  final int value;
  const BlendMode(this.value);

  static BlendMode fromValue(int value) => switch (value) {
    0 => GOPOST_BLEND_NORMAL,
    1 => GOPOST_BLEND_MULTIPLY,
    2 => GOPOST_BLEND_SCREEN,
    3 => GOPOST_BLEND_OVERLAY,
    _ => throw ArgumentError('Unknown value for BlendMode: $value'),
  };
}

enum ColorSpace {
  GOPOST_COLOR_SPACE_SRGB(0),
  GOPOST_COLOR_SPACE_DISPLAY_P3(1),
  GOPOST_COLOR_SPACE_ADOBE_RGB(2);

  final int value;
  const ColorSpace(this.value);

  static ColorSpace fromValue(int value) => switch (value) {
    0 => GOPOST_COLOR_SPACE_SRGB,
    1 => GOPOST_COLOR_SPACE_DISPLAY_P3,
    2 => GOPOST_COLOR_SPACE_ADOBE_RGB,
    _ => throw ArgumentError('Unknown value for ColorSpace: $value'),
  };
}

/// --- Canvas config ---
final class CanvasConfig extends ffi.Struct {
  @ffi.Int32()
  external int width;

  @ffi.Int32()
  external int height;

  @ffi.Float()
  external double dpi;

  @ffi.UnsignedInt()
  external int color_spaceAsInt;

  ColorSpace get color_space => ColorSpace.fromValue(color_spaceAsInt);

  @ffi.Float()
  external double bg_r;

  @ffi.Float()
  external double bg_g;

  @ffi.Float()
  external double bg_b;

  @ffi.Float()
  external double bg_a;

  @ffi.Int32()
  external int transparent_bg;
}

/// --- Layer info (read-only query result) ---
final class LayerInfo extends ffi.Struct {
  @ffi.Int32()
  external int id;

  @ffi.UnsignedInt()
  external int typeAsInt;

  LayerType get type => LayerType.fromValue(typeAsInt);

  @ffi.Array.multi([128])
  external ffi.Array<ffi.Char> name;

  @ffi.Float()
  external double opacity;

  @ffi.UnsignedInt()
  external int blend_modeAsInt;

  BlendMode get blend_mode => BlendMode.fromValue(blend_modeAsInt);

  @ffi.Int32()
  external int visible;

  @ffi.Int32()
  external int locked;

  /// translation
  @ffi.Float()
  external double tx;

  @ffi.Float()
  external double ty;

  /// scale
  @ffi.Float()
  external double sx;

  @ffi.Float()
  external double sy;

  /// degrees
  @ffi.Float()
  external double rotation;

  /// layer content pixel width
  @ffi.Int32()
  external int content_w;

  /// layer content pixel height
  @ffi.Int32()
  external int content_h;
}

typedef GopostFrameCallbackFunction =
    ffi.Void Function(
      ffi.Pointer<ffi.Void> user_data,
      ffi.Pointer<ffi.Void> texture_handle,
      ffi.Int32 width,
      ffi.Int32 height,
    );
typedef DartGopostFrameCallbackFunction =
    void Function(
      ffi.Pointer<ffi.Void> user_data,
      ffi.Pointer<ffi.Void> texture_handle,
      int width,
      int height,
    );

/// --- Frame callback for continuous rendering ---
typedef GopostFrameCallback =
    ffi.Pointer<ffi.NativeFunction<GopostFrameCallbackFunction>>;

const String GOPOST_MAGIC_BYTES = 'GOPT';

const int GOPOST_MAGIC_SIZE = 4;

const int GOPOST_FILE_HEADER_SIZE = 16;

const int GOPOST_ENCRYPTION_HEADER_SIZE = 64;
